__NUXT_JSONP__("/school-calendar", {data:[{details:{slug:"en",pageTitle:"MLI School Calendar | Mentor Language Institute",pageDescription:"The program strating date varies depending on F1 or Non F1 students.",title:"MLI School Calendar (2025-2026)",calendar:[{year:"2026",image:"\u002Fimages\u002Fcourses\u002Fschool-calendar\u002F2026.PNG"},{year:"2027",image:"\u002Fimages\u002Fcourses\u002Fschool-calendar\u002F2027.png"}],notes:["\u003Cfont color=\"#FECC13\"\u003EYellow\u003C\u002Ffont\u003E: Program Starting Date (Module)\u003Cbr \u002F\u003E\u003Cfont color=\"”#008000”\"\u003EGreen\u003C\u002Ffont\u003E： No school (Holiday)"],schoolCalendar:{title:"School Calendar (Program starting dates)",description:["The program strating date \u003Cspan class=\"ymarker\"\u003Evaries depending on F1 or Non F1 students.\u003C\u002Fspan\u003E"],lists:[{key:"Non F1 students who don't obtain a student visa.",value:["Can start their program on any Monday. \u003Cbr\u003EIf Monday is a holiday, then the program starting date will be Tuesday for that week."]},{key:"F1 students who obtain a student (F) visa.",value:["Can start on specific Mondays. (high-lighted in yellow on the Calendar).","\u003C2026\u003E \u003Cbr \u002F\u003E1\u002F20, 2\u002F17, 3\u002F16, 4\u002F13, 5\u002F11, 6\u002F8, 7\u002F6, 8\u002F3, 8\u002F31, 9\u002F28, 10\u002F26, 11\u002F23, 12\u002F21","\u003C2027\u003E\u003Cbr \u002F\u003E 1\u002F25, 2\u002F22, 3\u002F22, 4\u002F19, 5\u002F17, 6\u002F14, 7\u002F12, 8\u002F9, 9\u002F7, 10\u002F4, 11\u002F1, 11\u002F29","\u003C2028\u003E \u003Cbr \u002F\u003E 1\u002F3"]}]},faq:{title:"Frequently asked questions about arrival dates in the U.S.",lists:[{key:"\u003Cb\u003EQ: How many days before the program starting date can a student enter the U.S?\u003C\u002Fb\u003E",value:["A: MLI doesn't require our students to come to the U.S. a specific number of days in advance.\u003Cbr \u002F\u003EHowever, our students usually enter the U.S 1 or 2 days before their program starting dates."],note:"Note: International students are allowed to enter the U.S. 30 days prior to their program starting dates."},{key:"\u003Cb\u003EQ: Is it possible to move into the accommodation before the program starting dates?\u003C\u002Fb\u003E",value:["A: Yes. We can arrange your accommodation moving in date as any date.\u003Cbr \u002F\u003EIf there are other questions, please do not hesitate to consult us."]}]},dir:"\u002Fschool-calendar",path:"\u002Fschool-calendar\u002Fen",extension:".json",createdAt:"2026-10-22T16:31:30.868Z",updatedAt:"2026-04-24T11:47:24.279Z"}}],fetch:{},mutations:void 0});